// src/pages/About.js
import React from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import myPhoto from '../assets/images/foto.jpeg';

const About = () => {
  const { t } = useTranslation();

  const technical = t('about.tags', { returnObjects: true });
  const principles = t('about.principles', { returnObjects: true });
  const timeline = t('about.timeline', { returnObjects: true });
  const metrics = t('about.metrics', { returnObjects: true });
  const summary = t('about.summary', { returnObjects: true });

  return (
    <main className="page-shell">
      <header className="page-header">
        <span className="eyebrow">{t('about.eyebrow')}</span>
        <h1 className="page-title">{t('about.title')}</h1>
        <p className="page-lead">{t('about.lead')}</p>
      </header>

      <section className="content-split content-split--about">
        <aside className="panel panel--pad profile-card">
          <img src={myPhoto} alt={t('about.photoAlt')} className="profile-card__image" loading="lazy" />

          <div className="metric-grid metric-grid--compact">
            {metrics.map((metric) => (
              <div className="metric-card" key={metric.label}>
                <strong>{metric.value}</strong>
                <span>{metric.label}</span>
              </div>
            ))}
          </div>
        </aside>

        <section className="panel panel--pad">
          <p className="panel-kicker">{t('about.summaryKicker')}</p>
          {summary.map((paragraph) => (
            <p className="content-block" key={paragraph}>{paragraph}</p>
          ))}

          <div className="tag-list">
            {technical.map((item) => (
              <span key={item} className="tag">{item}</span>
            ))}
          </div>

          <div className="inline-actions">
            <Link className="btn btn-primary" to="/contact">{t('about.contact')}</Link>
            <Link className="btn btn-secondary" to="/projects">{t('about.viewProjects')}</Link>
          </div>
        </section>
      </section>

      <section className="section-block">
        <div className="detail-grid">
          <article className="panel panel--pad">
            <p className="panel-kicker">{t('about.principlesKicker')}</p>
            <ul className="bullet-list">
              {principles.map((item) => (
                <li key={item}>{item}</li>
              ))}
            </ul>
          </article>
        </div>
      </section>

      <section className="section-block">
        <div className="section-heading">
          <div>
            <span className="eyebrow">{t('about.timelineEyebrow')}</span>
            <h2 className="section-title">{t('about.timelineTitle')}</h2>
          </div>
        </div>

        <ol className="timeline-list">
          {timeline.map((item, index) => (
            <li key={`${item.period}-${index}`} className="timeline-item panel panel--pad">
              <p className="timeline-item__period">{item.period}</p>
              <h3 className="timeline-item__title">{item.title}</h3>
              <p className="timeline-item__detail">{item.detail}</p>
              <p className="timeline-item__description">{item.description}</p>
            </li>
          ))}
        </ol>
      </section>

    </main>
  );
};

export default About;

